Function mensaje <- StockDeLinea(linea As String)
  Define mensaje As String;
  Switch indexOf(linea, ";") Do
    Some(corte):
      mensaje <- substring(linea, 0, corte - 1) + " tiene " + substring(linea, corte + 1, length(linea) - 1);
    None: mensaje <- "Línea inválida";
  EndSwitch
EndFunction

Algorithm LeerLinea
  Define linea As String;
  Read linea;
  Write StockDeLinea(linea);
EndAlgorithm

