Function mensaje <- StockDeLinea(linea As String)
  Define mensaje As String;
  Define corte As Integer <- -1;
  For posicion <- 0 To length(linea) - 1 Do
    If substring(linea, posicion, posicion) = ";" Then
      corte <- posicion;
    EndIf
  EndFor
  If corte = -1 Then
    mensaje <- "Línea inválida";
  Else
    mensaje <- substring(linea, 0, corte - 1) + " tiene " + substring(linea, corte + 1, length(linea) - 1);
  EndIf
EndFunction

